  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
